        } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D66B") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 6))) {
          DataLineOrNoStatement ("           03 MOVEOUT-" + ($NOCASE) + "-" + ($K) + "    PIC X(06).  ")
        } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D86") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 8))) {
          DataLineOrNoStatement ("           03 MOVEOUT-" + ($NOCASE) + "-" + ($K) + "    PIC X(06).  ")
        } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D68") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 6))) {
          DataLineOrNoStatement ("           03 MOVEOUT-" + ($NOCASE) + "-" + ($K) + "    PIC X(08).  ")
        } else {
          Log-Message ("------------------------------------------------") '([LogMessageType]::Information)'
          Log-Message ("  ERREUR ERREUR ERREUR ERREUR ERREUR ERREUR     ") '([LogMessageType]::Information)'
          Log-Message ("------------------------------------------------") '([LogMessageType]::Information)'
