          Log-Message ("  SI PARAM = D24 ---> la date input est en 2 pos") '([LogMessageType]::Information)'
          Log-Message ("  SI PARAM = D22A---> la date input est en 2 pos") '([LogMessageType]::Information)'
          Log-Message ("  SI PARAM = D22B---> la date input est en 2 pos") '([LogMessageType]::Information)'
          Log-Message ("------------------------------------------------") '([LogMessageType]::Information)'
          $FLAGABORT = 1
        }
      } else {
        DataLineOrNoStatement ("           03 MOVEOUT-" + ($NOCASE) + "-" + ($K) + "  PIC X(" + ((GetSgsValue ("PG,$I,J,2"))) + ").")
      }
      If (((CompareTypeSafe (GetSgsValue ("PG,$I,$J,4")) "EqualTo" "D42") -and (CompareTypeSafe (GetSgsValue ("PG,$I,$J,2")) "EqualTo" 4))) {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - (2 + 1)))
      } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D24") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 2))) {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - (4 + 1)))
      } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D22A") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 2))) {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - (2 + 1)))
      } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D22B") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 2))) {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - (2 + 1)))
      } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D66A") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 6))) {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - (6 + 1)))
      } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D66B") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 6))) {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - (6 + 1)))
      } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D86") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 8))) {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - (6 + 1)))
      } elseif (((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D68") -and (CompareTypeSafe (GetSgsValue ("PG,$I,J,2")) "EqualTo" 6))) {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - (8 + 1)))
      } else {
        $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,J,3")) - ((GetSgsValue ("PG,$I,J,2")) + 1)))
      }
      If ((CompareTypeSafe $L2 "GreaterThan" 0)) {
        DataLineOrNoStatement ("           03 FILLER                   PIC X(" + ($L2) + ").")
      }
    }
    #  
    # cas du const 
    #  
  } elseif ((CompareTypeSafe (GetSgsValue ("PG,$I,1,1")) "EqualTo" "CONST")) {
    For ([Int32]$J = 2; $J -le (GetSgsValue ("PG,$I")); $J++) { 
      $K = ($J - 1)
      DataLineOrNoStatement ("       01  ENROUT-CONST-" + ($NOCASE) + "-" + ($K) + "   REDEFINES ENR-OUTPUT.  ")
      $L1 = ((GetSgsValue ("PG,$I,$J,1")) - 1)
      If ((CompareTypeSafe $L1 "GreaterThan" 0)) {
        DataLineOrNoStatement ("           03 FILLER                   PIC X(" + ($L1) + ").")
      }
      DataLineOrNoStatement ("           03 CONST-" + ($NOCASE) + "-" + ($K) + "  PIC X(" + ((GetSgsValue ("PG,$I,$J,2"))) + ").  ")
      $L2 = ((GetSgsValue ("FILEOUT,1,1,1")) - ((GetSgsValue ("PG,$I,$J,1")) - ((GetSgsValue ("PG,$I,$J,2")) + 1)))
      If ((CompareTypeSafe $L2 "GreaterThan" 0)) {
        DataLineOrNoStatement ("           03 FILLER                   PIC X(" + ($L2) + ").")
      }
    }
  }
}
