    }
    DataLineOrNoStatement ("       CASE-" + ($NOCASE) + ".  ")
    For ([Int32]$J = 2; $J -le (GetSgsValue ("PG,$I")); $J++) { 
      $K = ($J - 1)
      DataLineOrNoStatement ("           IF CASE-" + ($NOCASE) + "-" + ($K) + " = '" + ((GetSgsValue ("PG,$I,$J,3"))) + "'")
    }
  } elseif ((CompareTypeSafe (GetSgsValue ("PG,$I,1,1")) "EqualTo" "OTHERWISE")) {
    $NOCASE = ($NOCASE + 1)
    If ((CompareTypeSafe $NOCASE "NotEqualTo" 1)) {
