          DataLineOrNoStatement ("              MOVE WS-A2 TO MOVEOUT-" + ($NOCASE) + "-" + ($K) + "  ")
        } elseif ((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D66A")) {
