          DataLineOrNoStatement ("              PERFORM TRANSFO-DATE-66A THRU TRANSFO-DATE-66A-EXIT   ")
          DataLineOrNoStatement ("              MOVE WS-A6 TO MOVEOUT-" + ($NOCASE) + "-" + ($K) + "  ")
        } elseif ((CompareTypeSafe (GetSgsValue ("PG,$I,J,4")) "EqualTo" "D66B")) {
          DataLineOrNoStatement ("              MOVE MOVEIN-" + ($NOCASE) + "-" + ($K) + " TO WS-A6   ")
