DataLineOrNoStatement ("       TRANSFO-DATE-4-2.")
DataLineOrNoStatement ("      ******************")
DataLineOrNoStatement ("           MOVE WS-A4-AA TO WS-A2.  ")
DataLineOrNoStatement ("           IF ((WS-A4 > '1999') AND (WS-A4 < '2010'))   ")
