DataLineOrNoStatement ("           IF ((WS-A4 > '2009') AND (WS-A4 < '2020'))   ")
DataLineOrNoStatement ("              MOVE '_' TO WS-A2-A1. ")
DataLineOrNoStatement ("           IF ((WS-A4 > '2019') AND (WS-A4 < '2030'))   ")
DataLineOrNoStatement ("              MOVE '|' TO WS-A2-A1. ")
DataLineOrNoStatement ("           IF ((WS-A4 > '2029') AND (WS-A4 < '2040'))   ")
DataLineOrNoStatement ("              MOVE '~' TO WS-A2-A1. ")
DataLineOrNoStatement ("       TRANSFO-DATE-4-2-EXIT.   ")
DataLineOrNoStatement ("      ******************")
DataLineOrNoStatement ("           EXIT.")
DataLineOrNoStatement ("       TRANSFO-DATE-2-4.")
DataLineOrNoStatement ("      ******************")
DataLineOrNoStatement ("           IF WS-A2 = '00'  ")
DataLineOrNoStatement ("              MOVE '0000' TO WS-A4  ")
DataLineOrNoStatement ("              GO TO TRANSFO-DATE-2-4-EXIT.  ")
DataLineOrNoStatement ("           IF WS-A2 = '  '  ")
DataLineOrNoStatement ("              MOVE '    ' TO WS-A4  ")
DataLineOrNoStatement ("              GO TO TRANSFO-DATE-2-4-EXIT.  ")
DataLineOrNoStatement ("           IF WS-A2-A1 = ';'")
DataLineOrNoStatement ("              MOVE '20' TO WS-A4-SS ")
DataLineOrNoStatement ("              MOVE '0'  TO WS-A4-A1 ")
DataLineOrNoStatement ("              MOVE WS-A2-A2  TO WS-A4-A2")
DataLineOrNoStatement ("              GO TO TRANSFO-DATE-2-4-EXIT.  ")
DataLineOrNoStatement ("           IF WS-A2-A1 = '_'")
DataLineOrNoStatement ("              MOVE '20' TO WS-A4-SS ")
DataLineOrNoStatement ("              MOVE '1'  TO WS-A4-A1 ")
DataLineOrNoStatement ("              MOVE WS-A2-A2  TO WS-A4-A2")
DataLineOrNoStatement ("              GO TO TRANSFO-DATE-2-4-EXIT.  ")
DataLineOrNoStatement ("           IF WS-A2-A1 = '|'")
DataLineOrNoStatement ("              MOVE '20' TO WS-A4-SS ")
DataLineOrNoStatement ("              MOVE '2'  TO WS-A4-A1 ")
DataLineOrNoStatement ("              MOVE WS-A2-A2  TO WS-A4-A2")
DataLineOrNoStatement ("              GO TO TRANSFO-DATE-2-4-EXIT.  ")
